import{_ as s,o as t,c as l,a4 as o}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0071 — Libellés côté serveur : un catalogue pour le Core, un champ labels par extension, le libellé rendu à côté de la clé","description":"Extrait de docs/adr/0071-libelles-cote-serveur.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0071 — Libellés côté serveur : un catalogue pour le Core, un champ labels par extension, le libellé rendu à côté de la clé","description":"Extrait de docs/adr/0071-libelles-cote-serveur.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0071-libelles-cote-serveur.md","filePath":"developpeurs/adr/0071-libelles-cote-serveur.md"}'),r={name:"developpeurs/adr/0071-libelles-cote-serveur.md"};function n(a,e,i,d,c,u){return t(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0071--libellés-côté-serveur--un-catalogue-pour-le-core-un-champ-labels-par-extension-le-libellé-rendu-à-côté-de-la-clé" tabindex="-1">ADR-0071 — Libellés côté serveur : un catalogue pour le Core, un champ <code>labels</code> par extension, le libellé rendu à côté de la clé <a class="header-anchor" href="#adr-0071--libellés-côté-serveur--un-catalogue-pour-le-core-un-champ-labels-par-extension-le-libellé-rendu-à-côté-de-la-clé" aria-label="Permalink to &quot;ADR-0071 — Libellés côté serveur : un catalogue pour le Core, un champ `labels` par extension, le libellé rendu à côté de la clé {#adr-0071--libellés-côté-serveur--un-catalogue-pour-le-core-un-champ-labels-par-extension-le-libellé-rendu-à-côté-de-la-clé}&quot;">​</a></h1><p><strong>Date :</strong> 16 octobre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> issue #26 (lot 22) ; arbitrages du Product Owner du 16/10/2026 (catalogue serveur, déclaration par manifeste, résolution par l&#39;API, périmètre permissions et rôles, français d&#39;abord) <strong>Complète :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0002-frontiere-core-plugins">ADR-0002</a> (le SDK <code>app.plugins</code> reste la seule surface d&#39;une extension) ; <a href="/teuthis-cms-distribution/developpeurs/adr/0010-etat-installation-plugins-par-tenant">ADR-0010</a> (le manifeste) ; <a href="/teuthis-cms-distribution/developpeurs/adr/0048-site-du-projet-genere-depuis-le-depot">ADR-0048</a> (la rubrique Extensions lit le dépôt, ne recopie rien) <strong>Lève :</strong> l&#39;objection écrite dans l&#39;en-tête de <code>apps/admin/pages/comptes/roles.vue</code> (E6), qui faisait afficher les clés i18n brutes</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le Core nomme ses permissions et ses rôles par des <strong>clés i18n</strong>, jamais par des phrases (CDC §5.3) : <code>rbac.permission.organisation.gerer</code>, <code>rbac.role.editor</code>. Une extension fait de même (<code>plugins.sve.permission.traiter</code>). Mais <strong>rien, côté serveur, ne disait ce que ces clés voulaient dire</strong>. L&#39;écran « Rôles et permissions » du back-office et la rubrique Extensions du site du projet affichaient donc des clés brutes — illisibles pour un référent informatique qui n&#39;est pas développeur, et c&#39;est lui qui décide de ce que chaque rôle peut faire.</p><p>L&#39;en-tête de <code>roles.vue</code> justifiait ce choix : <em>inventer une traduction française locale donnerait une seconde table de libellés qui divergerait de celle du serveur au premier plugin installé.</em> L&#39;objection est juste <strong>tant que la table est dans l&#39;admin</strong> : elle ne connaîtrait pas le rôle « Agent d&#39;accueil » apporté par une extension, ni celui d&#39;une extension tierce. Elle ne tient plus si la table est <strong>celle du serveur</strong>, au même endroit que la clé qu&#39;elle explique, et si chaque extension y écrit ses propres libellés.</p><p>Le site du projet avait le même défaut, signalé comme une limite dans <code>site/scripts/exporter_extensions.py</code> : les libellés n&#39;existaient « que sous forme de clés », et la compétence du site interdisait d&#39;en inventer.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. Un catalogue de libellés côté serveur, par langue.</strong> Le module <code>app/i18n/</code> tient un <code>LabelCatalogue</code> : <code>{langue: {clé: libellé}}</code>, avec le propriétaire de chaque clé. Le Core y inscrit les siens dans <code>app/i18n/core.py</code> (<code>CORE_LABELS = {&quot;fr&quot;: {…}}</code>). Une clé a <strong>un seul propriétaire</strong> : enregistrer une clé déjà prise par un autre est refusé (<code>ValueError</code>), dans toutes les langues. Le module n&#39;importe rien du serveur, pour que le Core comme les extensions puissent en dépendre sans cycle.</p><p><strong>2. Chaque extension déclare les siens dans son manifeste : <code>labels</code>.</strong> Un <code>LabelTable</code> — <code>{&quot;fr&quot;: {&quot;plugins.sve.permission.traiter&quot;: &quot;Traiter les demandes de saisine&quot;}}</code> — validé à la <strong>construction</strong> du manifeste, avec les autres refus déjà posés (ADR-0002) :</p><ul><li><strong>clés dans l&#39;espace de l&#39;extension</strong> : <code>plugins.&lt;sa clé&gt;.…</code>. Une clé du Core ou d&#39;une autre extension est refusée, ce qui interdit à un plugin de faire mentir le libellé d&#39;une permission du Core au moment où un administrateur décide d&#39;un rôle ;</li><li><strong><code>label_key</code> des permissions et rôles de l&#39;extension dans ce même espace</strong> : sinon une permission pourrait emprunter le libellé d&#39;une autre clé (« Consulter les contenus » affiché sur une permission d&#39;export) ;</li><li>clés au format i18n existant (<code>I18nKey</code>, 120 caractères au plus) ; valeurs <strong>non vides, sur une ligne, 200 caractères au plus</strong> (espaces de bord retirés) ; langue lisible (<code>fr</code>, <code>en</code>, <code>fr-CA</code>) ; 10 langues et 500 libellés par langue au plus. Un manifeste est de la donnée fournie par un tiers : tout est borné.</li></ul><p>Le champ est facultatif : une extension sans <code>labels</code> reste valide et s&#39;affiche par ses clés. Le SDK (<code>app.plugins</code>) exporte <code>LabelTable</code> et <code>DEFAULT_LANGUAGE</code> ; une extension n&#39;importe toujours que <code>app.plugins</code>.</p><p><strong>3. Construit une fois, résolu en mémoire, jamais par requête.</strong> <code>PluginCatalogue.labels()</code> rend un <code>LabelResolver</code> (<code>app/plugins/labels.py</code>) — le Core, plus les libellés de tous les plugins <strong>déclarés</strong> —, construit au premier usage et jeté seulement quand un plugin s&#39;ajoute. <code>current_labels()</code> (<code>app/plugins/runtime.py</code>) donne celui du processus. Résoudre une clé est une recherche de dictionnaire : aucune requête SQL, donc aucun N+1 sur une liste de rôles (<code>CLAUDE.md</code>). Un test compte les requêtes d&#39;une même route avant et après l&#39;installation de deux extensions : le nombre ne bouge pas. La fonction générique est <code>LabelResolver.label(clé, langue)</code> : elle sert aujourd&#39;hui les permissions et les rôles, et servira telle quelle les autres familles de clés.</p><p><strong>4. L&#39;API rend le libellé résolu à côté de la clé.</strong> <code>label</code> (ou une table <code>…_labels</code> quand la réponse ne porte que des clés), <code>null</code> si le catalogue n&#39;en connaît pas. Ce qui change :</p><table tabindex="0"><thead><tr><th>Route</th><th>Ajout</th></tr></thead><tbody><tr><td><code>GET /rbac/roles</code></td><td><code>label</code> sur chaque rôle et chaque permission, à côté de <code>label_key</code></td></tr><tr><td><code>GET /access-profiles</code></td><td><code>staff_role_labels</code> : <code>{clé du rôle: libellé}</code></td></tr><tr><td><code>GET /plugins</code> et les routes d&#39;installation</td><td><code>permission_labels</code> (permissions apportées, demandées, accordées) et <code>role_labels</code></td></tr><tr><td>comptes (<code>GET /staff-users</code>, <code>/auth/me</code>, session)</td><td><code>role_label</code></td></tr></tbody></table><p><strong>5. Langue : le français, la structure prête pour l&#39;anglais.</strong> Le catalogue est un dictionnaire par langue ; <code>Accept-Language</code> choisit la langue demandée (<code>choose_language</code>, <code>requested_language</code>), avec repli sur la langue seule (<code>fr-CA</code> → <code>fr</code>) puis sur le français. Une langue inconnue n&#39;est jamais une erreur. Seul le français est rempli : l&#39;anglais viendra comme une seconde entrée de <code>CORE_LABELS</code> et des <code>labels</code> des manifestes, sans changer le mécanisme. Les <code>role_label</code> des comptes sont rendus dans la langue par défaut tant qu&#39;il n&#39;y a qu&#39;une langue.</p><p><strong>6. L&#39;admin et le site affichent le libellé, la clé en repli et en texte secondaire.</strong> Un composant <code>LabelledKey</code> montre le libellé suivi de la clé en <code>code</code> (la clé reste consultable, utile au développeur) ; sans libellé, la clé seule, comme avant — jamais un trou. Rien n&#39;est porté par la couleur seule. L&#39;en-tête de <code>roles.vue</code> et le commentaire de <code>utils/rbac.ts</code> disent désormais l&#39;inverse de ce qu&#39;ils disaient. La rubrique Extensions du site lit les libellés par l&#39;exporteur, depuis le catalogue (<code>catalogue.labels()</code>), jamais recopiés.</p><p><strong>7. Périmètre : le mécanisme vaut pour toutes les clés ; on remplit les permissions et les rôles.</strong> Les 28 permissions et les 5 rôles du Core, et les permissions et rôles des extensions livrées (SVE : 3 permissions et 1 rôle ; Développeurs : 2 permissions et 1 rôle ; les 27 autres n&#39;en déclarent aucun). Chaque libellé a été écrit <strong>après lecture de ce que la permission ouvre</strong> dans les routes qui la demandent, en français sobre : un verbe à l&#39;infinitif et son objet pour une permission (« Gérer l&#39;organisation »), un nom pour un rôle. <strong>Un test échoue si une permission ou un rôle livré n&#39;a pas de libellé français</strong> (<code>test_toute_permission_et_tout_role_livre_a_un_libelle_francais</code>) ; d&#39;autres refusent un libellé orphelin, un doublon ou un style qui n&#39;est pas « verbe à l&#39;infinitif + objet ».</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Une table de libellés dans l&#39;admin seulement</strong></td><td>C&#39;est l&#39;objection de <code>roles.vue</code> : elle ne connaît pas le rôle d&#39;une extension, doit être mise à jour à la main à chaque permission ajoutée, et le site du projet aurait eu une troisième table. Une extension tierce ne pourrait jamais apporter la sienne.</td></tr><tr><td><strong>Garder les clés brutes</strong></td><td>Ce qui existait. Honnête, mais inutilisable pour le public visé : un référent informatique ne peut pas décider d&#39;un rôle en lisant <code>rbac.permission.type_de_contenu.gerer</code>.</td></tr><tr><td><strong>Résoudre côté client, par une route <code>GET /labels</code> que l&#39;admin appelle puis applique</strong></td><td>Une requête et une jointure de plus côté navigateur, et chaque client (admin, site, front) aurait à refaire la résolution. Rendre le libellé dans la réponse qui cite la clé évite l&#39;écart entre ce qui est affiché et ce que le serveur sait.</td></tr><tr><td><strong>Les libellés en base, par organisation</strong></td><td>Une requête de plus par réponse (ou un cache à invalider), et une table à migrer pour une donnée qui est une propriété de la distribution, la même pour toutes les organisations. Un libellé personnalisable par organisation est une autre décision, qui pourra se superposer à celle-ci.</td></tr><tr><td><strong>Un fichier de libellés par langue, hors du code</strong></td><td>Sépare le libellé de la déclaration de la clé : le jour où une permission est renommée, rien ne la relie plus à sa phrase. Un test d&#39;exhaustivité sur des dictionnaires Python vit avec le code qu&#39;il garde.</td></tr><tr><td><strong>Une extension qui peut aussi poser un libellé du Core (« surcharge »)</strong></td><td>Refusé : une extension installée ne doit pas pouvoir changer ce que dit une permission du Core, sinon l&#39;écran des rôles ment à l&#39;administrateur au moment où il décide.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>L&#39;écran « Rôles et permissions », les formulaires de compte, la politique d&#39;authentification, l&#39;écran des plugins et la rubrique Extensions affichent des phrases, avec la clé en secondaire.</li><li>Une extension tierce apporte ses propres libellés, validés à sa construction, sans toucher au Core.</li><li>Ajouter une permission au Core sans écrire sa phrase fait échouer un test : le défaut ne peut pas arriver en production.</li><li>La résolution ne coûte aucune requête.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Une phrase à écrire pour chaque permission ou rôle</strong>, dans le même commit. C&#39;est voulu : c&#39;est ce qui garde la table exacte.</li><li><strong>Un libellé est une affirmation sur ce que fait une permission</strong> : quand le code change ce qu&#39;elle ouvre, le libellé doit suivre. Le test ne vérifie que sa présence et son style, pas son exactitude.</li><li><strong><code>sve.demande.cloturer</code> n&#39;est vérifiée par aucune route aujourd&#39;hui</strong> : elle est déclarée et portée par le rôle « Agent d&#39;accueil », mais clôturer une demande passe par <code>content.update</code>. Son libellé dit ce qu&#39;elle est destinée à ouvrir, pas ce qu&#39;elle ouvre encore. <em>Corrigé le 16/10/2026 (issue #29) : un réglage d&#39;enregistrement peut désormais réserver certaines de ses valeurs à une permission (<code>option_permissions</code>), et la SVE réserve l&#39;état « cloture » à <code>sve.demande.cloturer</code> ; y entrer comme en sortir exige la permission (403 sinon). Le libellé dit donc ce que la permission ouvre.</em></li><li>Le libellé du Core est en français seulement ; une extension tierce en <code>en</code> sans <code>fr</code> tomberait sur « pas de libellé » pour un lecteur francophone (le repli est le français, pas l&#39;anglais).</li><li>Les <code>role_label</code> des comptes et la description d&#39;une règle d&#39;accès de page (« les agents de rôle « editor » ») restent dans la langue par défaut ou en clé : leur routage par langue viendra avec l&#39;anglais.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Mécanisme, et libellés des permissions et rôles du Core et des extensions livrées. — <code>apps/api/app/i18n/</code> (<code>catalogue.py</code>, <code>core.py</code>, <code>http.py</code>), <code>apps/api/app/plugins/labels.py</code> (<code>LabelResolver</code>), <code>PluginManifest.labels</code> et ses validations (<code>apps/api/app/plugins/manifest.py</code>), <code>labels</code> de <code>apps/api/app/bundled_plugins/sve.py</code> et <code>developpeurs.py</code> ; réponses : <code>GET /rbac/roles</code>, <code>/access-profiles</code>, <code>/plugins</code>, comptes ; admin : <code>components/rbac/LabelledKey.vue</code> et les écrans <code>comptes/roles</code>, <code>comptes/agents/*</code>, <code>comptes/politique</code>, <code>mon-compte</code>, <code>plugins</code>, éditeur de profils d&#39;accès ; site : <code>site/scripts/exporter_extensions.py</code>, <code>generer/extensions.mjs</code>, <code>generer/sdk.mjs</code>. Preuves : <code>apps/api/tests/test_libelles.py</code> (60 tests : catalogue, validation du manifeste, exhaustivité, réponses, zéro requête de plus ; rouge sur l&#39;ancien code, vert après), <code>site/scripts/tests/site.test.mjs</code> (deux tests de plus) ; <code>bash scripts/verifier-comme-la-ci.sh api admin site</code> vert le 16/10/2026.</li><li>[ ] Remplir les autres familles de clés : aides de champ, filtres de liste, actions, fournisseurs d&#39;identité, états de cycle de vie, messages de notification — le mécanisme (<code>LabelResolver.label</code>) les sert déjà ; il reste à écrire les libellés, famille par famille, avec un test d&#39;exhaustivité chacune.</li><li>[ ] Ajouter l&#39;anglais : une entrée <code>&quot;en&quot;</code> dans <code>CORE_LABELS</code> et dans les <code>labels</code> des extensions livrées, puis acheminer la langue de l&#39;agent connecté jusqu&#39;aux <code>role_label</code> et aux règles d&#39;accès de page (aujourd&#39;hui rendus dans la langue par défaut).</li></ul>',26)])])}const g=s(r,[["render",n]]);export{m as __pageData,g as default};
